while_vmap.code:
def count_to(n, x):
    return lax.while_loop(lambda s: s[0] < n,
                          lambda s: (s[0] + 1, s[1] * 0.999 + 1.0), (0, x))

jax.vmap(count_to)(jnp.array([1, 10, 100, 1000]), jnp.zeros(4))

